 * Examples:
 * - getUrlForQuery('https://example.com/api/user', 'aBc123') returns 'https://example.com/api/user/aBc123'
 * - getUrlForQuery('https://example.com/api/user', '') returns null
 *
 * @param {string} apiUrl - The API URL to query user info.
 * @param {string} userId - The user ID to query.
 * @returns {string|null} - The URL for query.
 */
function getUrlForQuery(apiUrl, userId) {
  if (!userId || userId.trim() === '') {
    return null;
  }

  // The requirement is to concatenate the API URL with the user ID.
  // The examples show a direct concatenation without complex sanitization.
  // For security, it's generally recommended to encode the user ID to prevent
  // issues with special characters in URLs.
  // The original sanitization `replace(/[./\\]/g, '_')` was a basic attempt
  // but `encodeURIComponent` is the standard and more robust way to handle
  // characters that have special meaning in URLs.
  const encodedUserId = encodeURIComponent(userId);

  // Ensure there's a slash between apiUrl and userId if apiUrl doesn't end with one.
  // However, the examples imply a direct concatenation with a slash.
  // Let's stick to the example's implied behavior.
  return `${apiUrl}/${encodedUserId}`;
}
